import Root from "./3Escape Hatches/2SynchronizingwithEffect"
import {HandleInput as Fundamental} from "./2Managing State/3PreserrvingandResetting"
import Sub from "./subReLearn"
import Custom from "./customComponent"
import "./ReLearn.css"

import { useEffect, useRef, useState } from "react"

export default function() {
  const [bool, setBool] = useState(false)
  const ref = useRef(null)

  useEffect(() => {
    if (bool) {ref.current.innerHTML = "true"}
    else {ref.current.innerHTML = "false"}
  }, [bool])
  return <>
  <p ref={ref}></p>
  <button
  onClick={() => {setBool(!bool)}}
  >click</button>
  </>
}


